#[tokio::main]
async fn main() -> ResultWithDefaultError<()> {
    // Auto-load repo-local .env for local development without manual shell sourcing.
    // This ensures `cargo run` uses fake/test credentials instead of falling through
    // to macOS keychain-backed storage.
    let _ = dotenvy::from_filename_override(".env");
    let parsed_args = match Cli::try_parse() {
        Ok(cli) => cli,
        Err(err) => {
            if err.kind() == ErrorKind::InvalidSubcommand {
                let mut msg = err.to_string();
                msg.push_str("\nAvailable commands: auth, entry, project, tag, client, task, workspace, org, me, preferences, report, config, logout\n");
                eprint!("{msg}");
                std::process::exit(2);
            }
            // For all other errors (--help, --version, missing args, etc.), use clap's default handling
            err.exit();
        }
    };
    let json_mode = parsed_args.cmd.has_json_flag();
    match execute_subcommand(parsed_args).await {
        Ok(()) => Ok(()),
        Err(error) => {
            if json_mode {
                let msg = format!("{error}");
                let msg = msg.trim_end_matches('\n');
                let escaped = msg
                    .replace('\\', "\\\\")
                    .replace('"', "\\\"")
                    .replace('\n', "\\n");
                eprint!("{{\"error\":\"{escaped}\"}}");
            } else {
                eprint!("{error}");
            }
            std::process::exit(1);
        }
    }
}

async fn execute_subcommand(args: Cli) -> ResultWithDefaultError<()> {
    setup_working_directory(args.directory)?;

    let picker = picker::get_picker(false);

    match args.cmd {
        Command::Auth {
            action,
            api_token,
            api_type,
            api_url,
        } => match action {
            Some(AuthAction::Status { json }) => {
                let status = AuthStatusCommand::get_status();
                if json {
                    AuthStatusCommand::execute_json(io::stdout(), status)
                } else {
                    AuthStatusCommand::execute(io::stdout(), status)
                }
            }
            Some(AuthAction::Login {
                api_token: login_token,
                api_type: login_type,
                api_url: login_url,
            }) => {
                // Use login subcommand args if provided, otherwise fall back to positional args
                let token = login_token.or(api_token);
                let api_type = login_type.or(api_type);
                let api_url = login_url.or(api_url);
                execute_auth_command(token, api_type, api_url, args.proxy).await
            }
            None => {
                // Backward compatibility: `toggl auth <token>` without subcommand
                execute_auth_command(api_token, api_type, api_url, args.proxy).await
            }
        },
        Command::Logout => execute_logout_command().await,
        Command::Me { json } => {
            let api_client = get_api_client(args.proxy.clone())?;
            MeCommand::execute(api_client, json).await
        }
        Command::Entry { action } => execute_entry_command(action, args.proxy, picker).await,
        Command::Project { action } => {
            let api_client = get_api_client(args.proxy.clone())?;
            execute_project_command(action, api_client).await
        }
        Command::Tag { action } => {
            let api_client = get_api_client(args.proxy.clone())?;
            execute_tag_command(action, api_client).await
        }
        Command::Client { action } => {
            let api_client = get_api_client(args.proxy.clone())?;
            execute_client_command(action, api_client).await
        }
        Command::Task { action } => {
            let api_client = get_api_client(args.proxy.clone())?;
            execute_task_command(action, api_client).await
        }
        Command::Workspace { action } => {
            let api_client = get_api_client(args.proxy.clone())?;
            execute_workspace_command(action, api_client).await
        }
        Command::Org { action } => {
            let api_client = get_api_client(args.proxy.clone())?;
            execute_organization_command(action, api_client).await
        }
        Command::Preferences { action } => {
            let api_client = get_api_client(args.proxy.clone())?;
            execute_preferences_command(action, api_client).await
        }
        Command::Report { action } => {
            let api_client = get_api_client(args.proxy.clone())?;
            commands::report::execute_report_command(action, api_client).await
        }
        Command::Config {
            edit,
            delete,
            path,
            cmd,
        } => execute_config_command(edit, delete, path, cmd).await,
    }
}

fn setup_working_directory(directory: Option<std::path::PathBuf>) -> ResultWithDefaultError<()> {
    if let Some(dir) = directory {
        if !dir.exists() {
            return Err(Box::new(error::ArgumentError::DirectoryNotFound(dir)));
        }
        if !dir.is_dir() {
            return Err(Box::new(error::ArgumentError::NotADirectory(dir)));
        }
        std::env::set_current_dir(dir).expect("Couldn't set current directory");
    }
    Ok(())
}

async fn execute_entry_command(
    action: EntryAction,
    proxy: Option<String>,
    picker: Box<dyn picker::ItemPicker>,
) -> ResultWithDefaultError<()> {
    // Validate required arguments BEFORE creating the API client to avoid
    // unnecessary keychain/storage access for validation failures.
    match &action {
        EntryAction::Show { id, current, .. } if id.is_none() && !current => {
            return Err(Box::new(error::ArgumentError::MissingArgument(
                "'show' requires an entry ID or --current flag. Run `toggl entry list` or `toggl entry running` to find one.".to_string(),
            )));
        }
        EntryAction::Update { id, current, .. } if id.is_none() && !current => {
            return Err(Box::new(error::ArgumentError::MissingArgument(
                "'edit' requires an entry ID or --current flag. Example: toggl entry edit --current -d \"New description\"".to_string(),
            )));
        }
        EntryAction::Update {
            description,
            billable,
            project,
            task,
            tags,
            start,
            end,
            ..
        } if description.is_none()
            && billable.is_none()
            && project.is_none()
            && task.is_none()
            && tags.is_none()
            && start.is_none()
            && end.is_none() =>
        {
            return Err(Box::new(error::ArgumentError::MissingUpdateFields(
                "No fields specified to update. Use -d, -p, -t, --billable, --tags, --start, or --end to specify what to change.".to_string(),
            )));
        }
        EntryAction::Delete { id, current, .. } if id.is_none() && !current => {
            return Err(Box::new(error::ArgumentError::MissingArgument(
                "'delete' requires an entry ID or --current flag. Run `toggl entry list` to find entry IDs.".to_string(),
            )));
        }
        EntryAction::BulkEdit { json: None, .. } => {
            return Err(Box::new(error::ArgumentError::MissingArgument(
                "'bulk-edit' requires --json flag with JSON payload".to_string(),
            )));
        }
        _ => {}
    }

    let api_client = get_api_client(proxy.clone())?;

    match action {
        EntryAction::Current { json } => RunningTimeEntryCommand::execute(api_client, json).await,
        EntryAction::List {
            number,
            json,
            since,
            until,
        } => ListCommand::execute(api_client, number, json, since, until, None).await,
        EntryAction::Stop { json } => {
            StopCommand::execute(&api_client, StopCommandOrigin::CommandLine, json).await?;
            Ok(())

use crate::api;
use crate::arguments::{Entity, StatusFilter};
use crate::models;
use crate::utilities;
use api::client::ApiClient;
use chrono::{DateTime, Local};
use models::{ResultWithDefaultError, TimeEntry};
use std::io::{self, BufWriter, Write};

pub struct ListCommand;

/// Serialize a slice of TimeEntry references as a JSON array,
/// injecting a `"running"` boolean into each entry.
fn time_entries_to_json(entries: &[&TimeEntry]) -> String {
    let values: Vec<serde_json::Value> = entries
        .iter()
        .map(|entry| {
            let mut value = serde_json::to_value(entry).expect("failed to serialize time entry");
            if entry.is_running() {
                if let Some(obj) = value.as_object_mut() {
                    obj.insert("running".to_string(), serde_json::Value::Bool(true));
                }
            }
            value
        })
        .collect();
    serde_json::to_string(&values).expect("failed to serialize time entries to JSON")
}

fn write_entries_grouped_by_date(handle: &mut impl Write, entries: &[&TimeEntry]) {
    let mut current_date: Option<chrono::NaiveDate> = None;
    for entry in entries {
        let local_start: DateTime<Local> = entry.start.with_timezone(&Local);
        let date = local_start.date_naive();
        if current_date != Some(date) {
            if current_date.is_some() {
                writeln!(handle).expect("failed to print");
            }
            writeln!(handle, "── {} ──", date.format("%Y-%m-%d %A")).expect("failed to print");
            current_date = Some(date);
        }
        writeln!(handle, "{entry}").expect("failed to print");
    }
}

impl ListCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        count: Option<usize>,
        json_flag: bool,
        since: Option<String>,
        until: Option<String>,
        entity: Option<Entity>,
    ) -> ResultWithDefaultError<()> {
        let is_time_entry = matches!(entity, None | Some(Entity::TimeEntry { .. }));
        let has_date_filter = since.is_some() || until.is_some();

        if is_time_entry && has_date_filter {
            let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
            let stdout = io::stdout();
            let mut handle = BufWriter::new(stdout);
            let json = match &entity {
                Some(Entity::TimeEntry { json }) => json_flag || *json,
                _ => json_flag,
            };
            let entries = if json {
                api_client
                    .get_time_entries_filtered_minimal(since, until)
                    .await
            } else {
                api_client.get_time_entries_filtered(since, until).await
            };
            match entries {
                Err(error) => {
                    return Err(error);
                }
                Ok(mut entries) => {
                    entries.sort_by_key(|e| e.start);
                    let entries = entries
                        .iter()
                        .take(count.unwrap_or(usize::MAX))
                        .collect::<Vec<_>>();
                    if json {
                        let json_string = time_entries_to_json(&entries);
                        writeln!(handle, "{json_string}").expect("failed to print");
                    } else if entries.is_empty() {
                        eprintln!("No entries found.");
                    } else {
                        write_entries_grouped_by_date(&mut handle, &entries);
                    }
                }
            }
            return Ok(());
        }

        if let Some(Entity::Tag { json: entity_json }) = entity {
            let json = json_flag || entity_json;
            let user = api_client.get_user().await?;
            match api_client.get_tags(user.default_workspace_id).await {
                Err(error) => {
                    return Err(error);
                }
                Ok(tags) => {
                    let stdout = io::stdout();
                    let mut handle = BufWriter::new(stdout);
                    let tags = tags
                        .iter()
                        .take(count.unwrap_or(usize::MAX))
                        .collect::<Vec<_>>();
                    if json {
                        let json_string =
                            serde_json::to_string(&tags).expect("failed to serialize tags to JSON");
                        writeln!(handle, "{json_string}").expect("failed to print");
                    } else {
                        tags.iter()
                            .for_each(|tag| writeln!(handle, "{tag}").expect("failed to print"));
                    }
                }
            }
            return Ok(());
        }

        if let Some(Entity::Client {
            json: entity_json,
            status,
        }) = entity
        {
            let json = json_flag || entity_json;
            let user = api_client.get_user().await?;
            let api_status = match &status {
                StatusFilter::Active => None,
                StatusFilter::Archived => Some("archived".to_string()),
                StatusFilter::All => Some("both".to_string()),
                StatusFilter::Done => None,
            };
            match api_client
                .get_clients(user.default_workspace_id, api_status)
                .await
            {
                Err(error) => {
                    return Err(error);
                }
                Ok(clients) => {
                    let stdout = io::stdout();
                    let mut handle = BufWriter::new(stdout);
                    let clients = clients
                        .iter()
                        .take(count.unwrap_or(usize::MAX))
                        .collect::<Vec<_>>();
                    if json {
                        let json_string = serde_json::to_string(&clients)
                            .expect("failed to serialize clients to JSON");
                        writeln!(handle, "{json_string}").expect("failed to print");
                    } else {
                        clients
                            .iter()
                            .for_each(|c| writeln!(handle, "{c}").expect("failed to print"));
                    }
                }
            }
            return Ok(());
        }

        if let Some(Entity::Organization { json: entity_json }) = entity {
            let json = json_flag || entity_json;
            let organizations = api_client.get_organizations().await?;
            let stdout = io::stdout();
            let mut handle = BufWriter::new(stdout);
            let organizations = organizations
                .iter()
                .take(count.unwrap_or(usize::MAX))
                .collect::<Vec<_>>();
            if json {
                let json_string = serde_json::to_string(&organizations)
                    .expect("failed to serialize organizations to JSON");
                writeln!(handle, "{json_string}").expect("failed to print");
            } else {
                organizations.iter().for_each(|organization| {
                    writeln!(handle, "{organization}").expect("failed to print")
                });
            }
            return Ok(());
        }

        if let Some(Entity::Project {
            json: entity_json,
            status,
        }) = entity
        {
            let json = json_flag || entity_json;
            let projects = api_client.get_projects_list().await?;
            let stdout = io::stdout();
            let mut handle = BufWriter::new(stdout);
            let projects: Vec<_> = projects
                .iter()
                .filter(|p| match &status {
                    StatusFilter::Active => p.active,
                    StatusFilter::Archived => !p.active,
                    StatusFilter::All => true,
                    StatusFilter::Done => true,
