use crate::api::client::ApiClient;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use std::collections::HashMap;

const QUARTER_SECONDS: i64 = 15 * 60;
const MINIMUM_SECONDS: i64 = 30 * 60;

#[derive(Debug, PartialEq, Eq)]
pub struct ProjectInvoice {
    pub project: String,
    pub seconds: i64,
}

pub struct InvoiceCommand;

impl InvoiceCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client.get_time_entries_filtered(since, until).await?;
        let projects = summarize(&entries);

        if projects.is_empty() {
            println!("(no data)");
            return Ok(());
        }

        for project in &projects {
            println!("{}s  {}", project.seconds, project.project);
        }
        println!(
            "{}s  Total",
            projects.iter().map(|p| p.seconds).sum::<i64>()
        );
        Ok(())
    }
}

pub fn summarize(entries: &[TimeEntry]) -> Vec<ProjectInvoice> {
    let mut totals = HashMap::<String, i64>::new();

    for entry in entries
        .iter()
        .filter(|entry| entry.billable && entry.stop.is_some() && entry.duration > 0)
    {
        let rounded = ((entry.duration + QUARTER_SECONDS - 1) / QUARTER_SECONDS) * QUARTER_SECONDS;
        let charged = rounded.max(MINIMUM_SECONDS);
        let project = entry
            .project
            .as_ref()
            .map(|project| project.name.clone())
            .unwrap_or_else(|| "No Project".to_string());
        *totals.entry(project).or_default() += charged;
    }

    let mut projects: Vec<_> = totals
        .into_iter()
        .map(|(project, seconds)| ProjectInvoice { project, seconds })
        .collect();
    projects.sort_by(|a, b| {
        b.seconds
            .cmp(&a.seconds)
            .then_with(|| a.project.cmp(&b.project))
    });
    projects
}

